<script>import{signIn}from'../logic/auth.js';import{t}from'../logic/i18n.js';let{lang='fa'}=$props();let username=$state(localStorage.getItem('kz-rmu')||'');let password=$state('');let error=$state('');let loading=$state(false);let showPass=$state(false);let remember=$state(!!localStorage.getItem('kz-rmu'));function tspw(){showPass=!showPass}function trm(){remember=!remember;if(remember&&username)localStorage.setItem('kz-rmu',username);else localStorage.removeItem('kz-rmu')}function onUserInput(e){username=e.target.value;if(remember)localStorage.setItem('kz-rmu',username)}async function handleLogin(e){e.preventDefault();error='';loading=true;try{const r=await signIn(username,password);if(r.error){error=r.error;loading=false;return}if(remember)localStorage.setItem('kz-rmu',username);else localStorage.removeItem('kz-rmu');window.location.hash='#/home';window.location.reload()}catch(err){loading=false;error=t(lang,'loginFailed')}}</script><div class="lp"><div class="lc"><div class="ll"><span class="li2">◆</span><h1>{t(lang,'siteTitle')}</h1></div><p class="ls">{t(lang,'loginTitle')}</p><form class="lf" onsubmit={handleLogin}><div class="fg"><label class="fl" for="login-user">{t(lang,'username')}</label><input id="login-user" type="text" class="fi" autocomplete="username" bind:value={username} oninput={onUserInput} required dir="ltr"/></div><div class="fg"><label class="fl" for="login-pass">{t(lang,'password')}</label><div class="pw"><input id="login-pass" type={showPass?'text':'password'} class="fi" autocomplete="current-password" placeholder="••••••••" bind:value={password} required dir="ltr"/><button type="button" class="pt" onclick={tspw} tabindex="-1">{#if showPass}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" width="18" height="18"><path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/><line x1="1" y1="1" x2="23" y2="23"/></svg>{:else}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" width="18" height="18"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>{/if}</button></div></div><div class="fr"><input id="login-rm" type="checkbox" checked={remember} onchange={trm}/><label for="login-rm">{lang==='en'?'Remember me':'مرا به یاد بسپار'}</label></div>{#if error}<div class="fe"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg><span>{error}</span></div>{/if}<button type="submit" class="fb" disabled={loading}>{#if loading}<span class="sp"></span>{t(lang,'loggingIn')}{:else}<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" width="18" height="18"><path d="M15 3h4a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-4"/><polyline points="10 17 15 12 10 7"/><line x1="15" y1="12" x2="3" y2="12"/></svg>{t(lang,'login')}{/if}</button></form><p class="lft"><a href="#/home">{t(lang,'backToHome')}</a></p></div></div><style>.lp{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;overflow:hidden}.lc{width:min(420px,92vw);background:var(--color-bg-primary);border:1px solid var(--color-border);border-radius:var(--radius-lg);padding:clamp(1.5rem,5vw,2.25rem) clamp(1.25rem,4vw,2rem);box-shadow:var(--shadow-lg);animation:fu 300ms ease;max-height:calc(100% - 2rem);overflow-y:auto}@keyframes fu{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:translateY(0)}}.ll{display:flex;align-items:center;justify-content:center;gap:0.5rem;margin-bottom:0.2rem}.li2{font-size:clamp(1.8rem,5.5vw,2.4rem);color:var(--color-accent);line-height:1}.ll h1{font-size:clamp(1.1rem,3.5vw,1.35rem);color:var(--color-accent);margin:0;line-height:1.2;white-space:nowrap}.ls{text-align:center;color:var(--color-text-muted);font-size:var(--font-size-sm);margin-bottom:clamp(1.1rem,3vw,1.6rem)}.fg{margin-bottom:clamp(0.75rem,2vw,1rem)}.fl{display:block;font-size:var(--font-size-sm);font-weight:600;color:var(--color-text-secondary);margin-bottom:0.3rem}.fi{width:100%;padding:clamp(0.5rem,1.5vw,0.65rem) clamp(0.6rem,2vw,0.85rem);border:1px solid var(--color-border);border-radius:var(--radius-md);background:var(--color-bg-secondary);color:var(--color-text-primary);font-family:var(--font-body);font-size:var(--font-size-base);transition:border var(--transition-fast),box-shadow var(--transition-fast);outline:none;box-sizing:border-box}.fi:focus{border-color:var(--color-accent);box-shadow:0 0 0 3px var(--color-accent-bg)}.pw{position:relative;display:flex;align-items:center}.pw .fi{padding-inline-end:2.5rem}.pt{position:absolute;inset-inline-end:0.55rem;display:flex;align-items:center;justify-content:center;width:28px;height:28px;border:none;background:none;color:var(--color-text-muted);cursor:pointer;border-radius:var(--radius-sm);transition:color var(--transition-fast);padding:0}.pt:hover{color:var(--color-text-secondary)}.fr{display:flex;align-items:center;gap:0.5rem;margin-bottom:clamp(0.85rem,2.5vw,1.1rem);font-size:var(--font-size-sm);color:var(--color-text-secondary)}.fr input[type=checkbox]{width:1rem;height:1rem;accent-color:var(--color-accent);cursor:pointer;margin:0}.fr label{cursor:pointer;user-select:none}.fe{display:flex;align-items:flex-start;gap:0.45rem;padding:0.55rem 0.7rem;background:#fef2f2;border:1px solid #fecaca;border-radius:var(--radius-md);color:#dc2626;font-size:var(--font-size-sm);margin-bottom:clamp(0.7rem,2vw,1rem);line-height:1.4}:global([data-theme="dark"]) .fe{background:#450a0a;border-color:#7f1d1d;color:#fca5a5}.fe svg{flex-shrink:0;margin-top:1px}.fb{width:100%;padding:clamp(0.55rem,1.5vw,0.7rem);border:none;border-radius:var(--radius-md);background:var(--color-accent);color:var(--color-accent-text);font-family:var(--font-body);font-size:var(--font-size-base);font-weight:600;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:0.5rem;transition:background var(--transition-fast)}.fb:hover:not(:disabled){background:var(--color-accent-dark)}.fb:disabled{opacity:0.65;cursor:not-allowed}.sp{width:18px;height:18px;border:2px solid rgba(255,255,255,0.3);border-top-color:#fff;border-radius:50%;animation:spi 0.6s linear infinite}@keyframes spi{to{transform:rotate(360deg)}}.lft{text-align:center;margin-top:clamp(0.7rem,2vw,1.1rem);font-size:var(--font-size-sm)}.lft a{color:var(--color-link)}</style>